import React, { useState } from "react";
import "../styles/Chat.css";

const Chat = () => {

    const [input, setInput] = useState("");

    const [normalMessages, setNormalMessages] = useState([]);
    const [forgetMessages, setForgetMessages] = useState([]);

    const sendMessage = async () => {
        if (!input) return;

        const userMsg = { text: input, sender: "user" };

        setNormalMessages(prev => [...prev, userMsg]);
        setForgetMessages(prev => [...prev, userMsg]);

        setNormalMessages(prev => [...prev, { text: "Thinking...", sender: "ai" }]);
        setForgetMessages(prev => [...prev, { text: "Thinking...", sender: "ai" }]);

        try {
            console.log("Sending to normal AI...");
            const normalRes = await fetch("http://localhost:5000/api/chat/normal", {
                method: "POST",
                headers: { "Content-Type": "application/json" },
                body: JSON.stringify({ message: input })
            });
            console.log("Normal res status:", normalRes.status, normalRes.statusText);

            console.log("Sending to forget AI...");
            const forgetRes = await fetch("http://localhost:5000/api/chat", {
                method: "POST",
                headers: { "Content-Type": "application/json" },
                body: JSON.stringify({ message: input })
            });
            console.log("Forget res status:", forgetRes.status, forgetRes.statusText);

            const normalData = await normalRes.json();
            const forgetData = await forgetRes.json();

            console.log("Normal data:", normalData);
            console.log("Forget data:", forgetData);

            // Replace thinking with real responses
            setNormalMessages(prev => [...prev.slice(0, -1), { text: normalData.reply || "No response from normal AI", sender: "ai" }]);
            setForgetMessages(prev => [...prev.slice(0, -1), { text: forgetData.reply || "No response from forget AI", sender: "ai" }]);

        } catch (err) {
            console.error("Chat Error:", err);
            setNormalMessages(prev => [...prev.slice(0, -1), { text: "Error: " + err.message, sender: "ai" }]);
            setForgetMessages(prev => [...prev.slice(0, -1), { text: "Error: " + err.message, sender: "ai" }]);
        }

        setInput("");
    };
    return (
        <div className="chat-page">

            {/* LEFT SIDE */}
            <div className="chat-panel">

                <h2>Normal AI 🤖</h2>
                <p className="subtitle">Remembers everything</p>

                <div className="chat-box">
                    {normalMessages.map((msg, i) => (
                        <div key={i} className={msg.sender}>
                            {msg.text}
                        </div>
                    ))}
                </div>

            </div>

            {/* RIGHT SIDE */}
            <div className="chat-panel">

                <h2>Forgetting AI 🧠</h2>
                <p className="subtitle">Forgets intelligently</p>

                <div className="chat-box">
                    {forgetMessages.map((msg, i) => (
                        <div key={i} className={msg.sender}>
                            {msg.text}
                        </div>
                    ))}
                </div>

            </div>

            {/* INPUT (COMMON) */}
            <div className="input-container">
                <input
                    value={input}
                    onChange={(e) => setInput(e.target.value)}
                    placeholder="Ask something..."
                />
                <button onClick={sendMessage}>Send</button>
            </div>

        </div>
    );
};

export default Chat;
